from collections.abc import Mapping
import operator

class _Base1:
    def validate_abstract_methods(self, abc, *names):
        methodstubs = dict.fromkeys(names, lambda s, *args: 0)
        C = type('C', (abc,), methodstubs)
        C()
        for name in names:
            stubs = methodstubs.copy()
            del stubs[name]
            C = type('C', (abc,), stubs)
            try:
                C()
            except TypeError as _e:
                print('raises', type(_e).__name__)
            else:
                print('NO-RAISE')
    def validate_comparison(self, instance):
        ops = ['lt', 'gt', 'le', 'ge', 'ne', 'or', 'and', 'xor', 'sub']
        operators = {}
        for op in ops:
            name = '__' + op + '__'
            operators[name] = getattr(operator, name)
        class Other:
            def __init__(self): self.right_side = False
            def __eq__(self, other): self.right_side = True; return True
            __lt__ = __eq__
            __gt__ = __eq__
            __le__ = __eq__
            __ge__ = __eq__
            __ne__ = __eq__
            __ror__ = __eq__
            __rand__ = __eq__
            __rxor__ = __eq__
            __rsub__ = __eq__
        for name, op in operators.items():
            if not hasattr(instance, name):
                continue
            other = Other()
            op(instance, other)
            print(repr(bool(other.right_side)))

class TestCollectionABCs(_Base1):
    def test_Mapping(self):
        for sample in [dict]:
            print(isinstance(sample(), Mapping))
            print(repr(bool(issubclass(sample, Mapping))))
        self.validate_abstract_methods(Mapping, '__iter__', '__len__', '__getitem__')
        class MyMapping(Mapping):
            def __len__(self): return 0
            def __getitem__(self, i): raise IndexError
            def __iter__(self): return iter(())
        self.validate_comparison(MyMapping())
        try:
            reversed(MyMapping())
        except TypeError as _e:
            print('raises', type(_e).__name__)
        else:
            print('NO-RAISE')

_t = TestCollectionABCs()
_t.test_Mapping()

