// ABCMeta.__instancecheck__ (the C _abc_instancecheck).
fn abc_instancecheck(cls: &Rc<Class>, x: &V) -> Result<bool, E> {
    let subtype = type_of(x);
    let subclass = match x {
        V::Obj(o) => o.cls.clone(),
        // Iterators are all one value type in the runtime; collections.abc sees the kind the It holds.
        V::Iter(it) => {
            let kind = {
                let it = it.borrow();
                match &it.it {
                    It::Gen(_) | It::GenExp(..) => ext_class("generator"),
                    It::Coro(_) => ext_class("coroutine"),
                    _ => ext_class("iterator"),
                }
            };
            kind
        }
        _ => subtype.clone(),
    };

